import{_ as r,K as d,a as n,c as s,ac as e,b as l,q as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"网球规则 · 适用范围与版本说明至七、抢十与无占先：先看规程再记分","description":"网球单打与双打的场地、发球、局盘计分、抢七、抢十和常见判例","frontmatter":{"title":"网球规则 · 适用范围与版本说明至七、抢十与无占先：先看规程再记分","description":"网球单打与双打的场地、发球、局盘计分、抢七、抢十和常见判例","splitFrom":"life/personal/sports/tennis-rules.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"网球规则","summary":"网球单打与双打的场地、发球、局盘计分、抢七、抢十和常见判例","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"网球规则","link":"/life/personal/sports/tennis-rules"},"next":{"text":"网球规则 · 八、用三个场景把比分读完整至官方来源与复核入口","link":"/life/personal/sports/tennis-rules-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"网球规则","link":"/life/personal/sports/tennis-rules"},"next":{"text":"网球规则 · 八、用三个场景把比分读完整至官方来源与复核入口","link":"/life/personal/sports/tennis-rules-part-02"}},"headers":[],"relativePath":"life/personal/sports/tennis-rules-part-01.md","filePath":"life/personal/sports/tennis-rules-part-01.md"}'),i={name:"life/personal/sports/tennis-rules-part-01.md"};function p(h,t,c,u,b,g){const a=d("ArticleImage");return n(),s("div",null,[t[0]||(t[0]=e('<h1 id="网球规则-·-适用范围与版本说明至七、抢十与无占先-先看规程再记分" tabindex="-1">网球规则 · 适用范围与版本说明至七、抢十与无占先：先看规程再记分 <a class="header-anchor" href="#网球规则-·-适用范围与版本说明至七、抢十与无占先-先看规程再记分" aria-label="Permalink to &quot;网球规则 · 适用范围与版本说明至七、抢十与无占先：先看规程再记分&quot;">​</a></h1><p><a href="/life/personal/sports/tennis-rules">返回分篇目录</a></p><p>网球先争每一分，再由分组成局、由局组成盘，最后按盘数决定胜负。入门最容易混淆的不是击球动作，而是发球顺序、40 平后的计分，以及不同赛事采用的决胜办法。</p><h2 id="网球规则" tabindex="-1">网球规则 <a class="header-anchor" href="#网球规则" aria-label="Permalink to &quot;网球规则 {#网球规则}&quot;">​</a></h2><p>网球先争每一分，再由分组成局、由局组成盘，最后按盘数决定胜负。入门最容易混淆的不是击球动作，而是发球顺序、40 平后的计分，以及不同赛事采用的决胜办法。</p><h2 id="适用范围与版本说明" tabindex="-1">适用范围与版本说明 <a class="header-anchor" href="#适用范围与版本说明" aria-label="Permalink to &quot;适用范围与版本说明 {#适用范围与版本说明}&quot;">​</a></h2><p>本文按 ITF《2026 Rules of Tennis》介绍成人单打与双打，区分常规计分和赛事可选赛制，图文核对日期为 2026 年 10 月 24 日。正式参赛应特别确认本赛事的决胜盘、无占先及发球擦网处理办法。</p><h2 id="一、场地、边界与比赛目标" tabindex="-1">一、场地、边界与比赛目标 <a class="header-anchor" href="#一、场地、边界与比赛目标" aria-label="Permalink to &quot;一、场地、边界与比赛目标 {#一、场地、边界与比赛目标}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>标准规格或规则</th></tr></thead><tbody><tr><td>场地长度</td><td>23.77 米</td></tr><tr><td>单打宽度</td><td>8.23 米，使用内侧边线</td></tr><tr><td>双打宽度</td><td>10.97 米，使用外侧边线</td></tr><tr><td>球网高度</td><td>中央 0.914 米，网柱处 1.07 米</td></tr><tr><td>发球线</td><td>距球网 6.40 米，与中线共同划出左右发球区</td></tr><tr><td>比赛人数</td><td>单打每方 1 人，双打每方 2 人</td></tr></tbody></table><p>压线球算界内：球只要触及有效区域的边界线，就算落在该区域。单打两侧的双打边道属于界外。双打回合中边道有效，但<strong>发球区仍使用相同的左右小格，不扩大到双打边道</strong>。</p><p>每一分的目标是把球合法击入对方有效场区，并使对手不能在第二次落地前合法回球。除接发球外，可以凌空击球；接发球者必须让发球先落地。</p><h2 id="看图理解单打、双打与发球区" tabindex="-1">看图理解单打、双打与发球区 <a class="header-anchor" href="#看图理解单打、双打与发球区" aria-label="Permalink to &quot;看图理解单打、双打与发球区 {#看图理解单打、双打与发球区}&quot;">​</a></h2>',12)),l("p",null,[o(a,{src:"/images/sports/tennis-court.svg",alt:"网球场比例图：单双打边线、左右发球区及从右区斜线发球的路线"})]),t[1]||(t[1]=e('<p><em>图：按 23.77 × 10.97 米绘制，内侧两条长线之间为单打宽度 8.23 米。两侧浅蓝边道在双打相持中有效，发球的小格仍在单打边线以内；棕色落点区演示下方球员从自己右侧发球的目标区。球网画成横线，不表现高度。</em></p><p><strong>“双打场地更宽”和“双打发球区更宽”是不同命题，后者不成立。</strong> 双打发球落进边道，哪怕没有超出双打边线，也属于发球失误。反过来，发球线不是相持的后界，正常回球可以落在发球线与底线之间。</p><h2 id="二、分、局、盘、场如何计算" tabindex="-1">二、分、局、盘、场如何计算 <a class="header-anchor" href="#二、分、局、盘、场如何计算" aria-label="Permalink to &quot;二、分、局、盘、场如何计算 {#二、分、局、盘、场如何计算}&quot;">​</a></h2><h3 id="一局-0、15、30、40" tabindex="-1">一局：0、15、30、40 <a class="header-anchor" href="#一局-0、15、30、40" aria-label="Permalink to &quot;一局：0、15、30、40 {#一局-0、15、30、40}&quot;">​</a></h3><p>普通局按 0、15、30、40 报分，先报发球方分数。双方 40 平称为平分；采用占先制时，一方需要在平分后连续赢两分，先赢一分取得占先，再赢一分才拿下这一局。占先方丢分，就回到平分。</p><p>例如发球方 40∶30，再赢一分就赢局；40 平后接发球方赢一分，是接发球方占先。下一分发球方赢，比分回到平分，不是变成“各自占先一次”。</p><h3 id="一盘-长盘与抢七盘" tabindex="-1">一盘：长盘与抢七盘 <a class="header-anchor" href="#一盘-长盘与抢七盘" aria-label="Permalink to &quot;一盘：长盘与抢七盘 {#一盘-长盘与抢七盘}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>赛制</th><th>结束方式</th></tr></thead><tbody><tr><td>长盘制</td><td>先赢至少 6 局且领先 2 局；6∶6 后继续打普通局，可到 8∶6、10∶8等</td></tr><tr><td>抢七盘制</td><td>一方先到 6 局并领先 2 局结束；6∶6 时通常进行抢七，胜者以 7∶6 赢盘</td></tr><tr><td>短盘或其他赛制</td><td>局数和触发抢七的条件由赛事另定，不能直接套用标准六局盘</td></tr></tbody></table><p>普通抢七按 0、1、2、3……累计小分，先到至少 7 分且领先 2 分获胜，因此 7∶6 还没有结束，8∶6 才结束。整场常见三盘两胜，也有五盘三胜；不能因为是职业网球就认定所有比赛都打五盘。</p><h2 id="三、发球程序与常见失误" tabindex="-1">三、发球程序与常见失误 <a class="header-anchor" href="#三、发球程序与常见失误" aria-label="Permalink to &quot;三、发球程序与常见失误 {#三、发球程序与常见失误}&quot;">​</a></h2><p>赛前通过掷币等方式决定先发球、接发球或选场。普通局由同一名球员发完整局，下一局换对方发球。每局第一分从右区发球，随后左右交替。</p><p>发球员站在底线后、中心标志与相应边线的假想延长线之间，将球抛出后在落地前击球，发向斜对角发球区。发球动作中不能踩到底线或越过规定位置，也不能通过走动、跑动改变位置，小幅自然脚步移动不等于跑动发球。</p><p>每分通常有两次发球机会。第一次发球出界、下网或脚误，仍可二发；第二次再失误，称为双误，对方得分。抛球后决定不击球而接住，通常不算发球失误；挥拍试图击球却没击中，则属于发球失误。</p><p>发球擦网后仍落入正确发球区，按标准规则判发球重发，重发该次发球，不消耗次数。<strong>二发擦网重发仍是二发，不恢复一发</strong>。某些赛事可采用经批准的“不重发”替代办法，赛前应先确认。</p><p>接发球者必须等球落地。发球在落地前击中接发球者或其同伴，通常是发球方得分，即使该球看上去将飞出界；接发球者不能用接住球来代替裁判的出界判断。</p><h2 id="四、抢七的发球和换边" tabindex="-1">四、抢七的发球和换边 <a class="header-anchor" href="#四、抢七的发球和换边" aria-label="Permalink to &quot;四、抢七的发球和换边 {#四、抢七的发球和换边}&quot;">​</a></h2><p>抢七的第一分由轮到下一局发球的人发，从右区开始。第一位发球员只发 1 分；对手接着发 2 分，然后双方每人轮流发 2 分，直到结束。</p><p>假设 A 是第一发球员，单打顺序如下：</p><table tabindex="0"><thead><tr><th>小分序号</th><th>发球员</th><th>发球区</th></tr></thead><tbody><tr><td>第 1 分</td><td>A</td><td>右区</td></tr><tr><td>第 2、3 分</td><td>B</td><td>左区、右区</td></tr><tr><td>第 4、5 分</td><td>A</td><td>左区、右区</td></tr><tr><td>第 6、7 分</td><td>B</td><td>左区、右区</td></tr><tr><td>第 8、9 分</td><td>A</td><td>左区、右区</td></tr></tbody></table><p>标准抢七双方每打完 <strong>6 分</strong>交换场地，包括 3∶3、6∶6、9∶9 等时刻；换边不改变原有发球轮转。不要把普通局的“奇数局换边”套进抢七的小分。</p><p>抢七结束后的下一盘，由抢七第一分的发球方先接发球。普通盘则在第 1、3、5 等奇数局结束后换边；盘结束时若总局数为偶数，要等下一盘第一局结束再换边。</p><h2 id="五、双打怎样轮转" tabindex="-1">五、双打怎样轮转 <a class="header-anchor" href="#五、双打怎样轮转" aria-label="Permalink to &quot;五、双打怎样轮转 {#五、双打怎样轮转}&quot;">​</a></h2><p>双打同队两人可以在每盘开始时决定谁先发球，但一旦建立本盘顺序就不能随意更改。假设甲队 A、B，乙队 C、D，先后选择 A、C 发球，则局与局之间依次为 <strong>A → C → B → D → A</strong>。</p><p>每队在本盘第一次接发球局开始前决定谁接右区、谁接左区，这个接发球分工在整盘保持不变。进入回合后两人可以自由移动、互换网前与底线位置，但下一次接发球仍按已确定的区位轮转。</p><p>双打抢七延续该盘发球顺序。例如轮到 A 发第一分，接下来 C 发两分、B 发两分、D 发两分，再由 A 发两分。不是一队连续发两人，也不是谁站在底线谁发球。</p><p>回合中同一队只能由一名队员完成这一拍，不能两人连续各击一次把球传过去。球击中队员身体或随身物品，通常该队失分；因此网前同伴也必须避开发球和回球。</p><h2 id="六、常见失分与判例" tabindex="-1">六、常见失分与判例 <a class="header-anchor" href="#六、常见失分与判例" aria-label="Permalink to &quot;六、常见失分与判例 {#六、常见失分与判例}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>标准判定</th></tr></thead><tbody><tr><td>回球在对方有效区域压线</td><td>好球，继续比赛</td></tr><tr><td>球在本方场地第二次落地后才击回</td><td>本方失分</td></tr><tr><td>正常回球擦网后落入对方有效区域</td><td>好球，继续比赛；发球擦网另有规则</td></tr><tr><td>球仍在比赛中，球拍、身体或衣物碰网</td><td>触网方失分</td></tr><tr><td>球碰到球员身体，即使人站在界外</td><td>被击中方通常失分，不能直接认定球已出界</td></tr><tr><td>有意把球停在拍上再抛送，或故意连续两次击球</td><td>失分；一次连续击球动作中的意外双碰另当别论</td></tr><tr><td>球绕过网柱后落在对方有效场地</td><td>可以是合法回球，不要求必须从球网上方越过</td></tr></tbody></table><p>不能在球尚未越网时主动伸拍去击球，但合法击球后的随挥可以越网，只要不触网或妨碍对手。特殊例外是球先在本方有效场地落地后，因旋转或风吹弹回对方半场，球员可依法越网击球；仍须避免触网、接触对方场地或妨碍对手。</p><p>分结束后碰网不追溯判罚：关键是触网时球是否仍处于比赛中。故意喊叫、动作等干扰对手可能直接丢分；非故意干扰或外来干扰是否重赛，由裁判结合发生时机判断。</p><h2 id="七、抢十与无占先-先看规程再记分" tabindex="-1">七、抢十与无占先：先看规程再记分 <a class="header-anchor" href="#七、抢十与无占先-先看规程再记分" aria-label="Permalink to &quot;七、抢十与无占先：先看规程再记分 {#七、抢十与无占先-先看规程再记分}&quot;">​</a></h2><p><strong>无占先制</strong>取消 40 平后的反复占先，40 平时打一分决胜，接发球方通常选择在右区或左区接这分。双打不能借选择发球区临时交换接发球员；混双有同一性别接发球的特别规定，依赛事采用的条款执行。</p><p><strong>比赛抢十</strong>常被用于替代决胜盘：先到至少 10 分且领先 2 分者赢下比赛，发球轮转原则与抢七相同。它不是先到 10 分就必胜，10∶9 仍须继续。</p><p>还要区分“整盘被比赛抢十替代”和“决胜盘先打普通局，6∶6 后再进行 10 分抢七”。两者触发条件、比分记录不同。看到“决胜盘抢十”时应读完整规程，不要凭简称推断。</p>',34))])}const _=r(i,[["render",p]]);export{m as __pageData,_ as default};
